1: using System.Collections;
2: using System.Linq;
3: using System.Text.Json;
4: 
5: namespace SecTester.Scan.CI;
6: 
7: internal class VendorMatcher
8: {
9:   private readonly IDictionary _env;
10: 
11:   public VendorMatcher(IDictionary env)
12:   {
13:     _env = env;
14:   }
15: 
16:   public bool MatchEnvElement(JsonElement element)
17:   {
18:     return element.ValueKind switch
19:     {
20:       JsonValueKind.String => element.GetString() is not null && _env.Contains(element.GetString()!),
21:       JsonValueKind.Object => MatchInnerAny(element) || MatchInnerEnvIncludes(element) ||
22:                               MatchOwnProperties(element),
23:       JsonValueKind.Array => element.EnumerateArray()
24:         .All(x => x.ValueKind == JsonValueKind.String && x.GetString() is not null && _env.Contains(x.GetString()!)),
25:       _ => false
26:     };
27:   }
28: 
29: 
30:   public bool MatchPrElement(JsonElement element)
31:   {
32:     return element.ValueKind switch
33:     {
34:       JsonValueKind.String => element.GetString() is not null && _env.Contains(element.GetString()!),
35:       JsonValueKind.Object => MatchInnerEnvNe(element) || MatchEnvElement(element),
36:       _ => false
37:     };
38:   }
39: 
40:   private bool MatchOwnProperties(JsonElement element)
41:   {
42:     return element.EnumerateObject().All(x =>
43:       x.Value.ValueKind == JsonValueKind.String && _env.Contains(x.Name) &&
44:       x.Value.ValueEquals(_env[x.Name]?.ToString()));
45:   }
46: 
47:   private bool MatchInnerAny(JsonElement element)
48:   {
49:     var any = element.EnumerateObject().FirstOrDefault(x => x.NameEquals("any"));
50: 
51:     return any.Value.ValueKind == JsonValueKind.Array && any.Value.EnumerateArray()
52:       .Any(x => x.ValueKind == JsonValueKind.String && x.GetString() is not null && _env.Contains(x.GetString()!));
53:   }
54: 
55:   private bool MatchInnerEnvIncludes(JsonElement element)
56:   {
57:     var env = GetInnerPropertyValue(element, "env");
58:     var includes = GetInnerPropertyValue(element, "includes");
59: 
60:     if (env is null || includes is null || !_env.Contains(env))
61:     {
62:       return false;
63:     }
64: 
65:     var envVarValue = _env[env]?.ToString();
66:     return envVarValue?.Contains(includes) ?? false;
67:   }
68: 
69:   private bool MatchInnerEnvNe(JsonElement element)
70:   {
71:     var env = GetInnerPropertyValue(element, "env");
72:     var ne = GetInnerPropertyValue(element, "ne");
73: 
74:     if (env is null || ne is null || !_env.Contains(env) || ne != "false")
75:     {
76:       return false;
77:     }
78: 
79:     var envVarValue = _env[env]?.ToString();
80:     return !string.IsNullOrEmpty(envVarValue);
81:   }
82: 
83:   private static string? GetInnerPropertyValue(JsonElement element, string name)
84:   {
85:     var property = element.EnumerateObject().FirstOrDefault(x => x.NameEquals(name));
86:     return property.Value.ValueKind == JsonValueKind.String ? property.Value.GetString() : default;
87:   }
88: }

